class Solution {
public:
 int minSwaps(vector<int>& nums){
  int n=nums.size(),ones=accumulate(nums.begin(),nums.end(),0);if(!ones)return 0;
  int cur=0;for(int i=0;i<ones;++i)cur+=nums[i];int best=cur;
  for(int i=ones;i<ones+n;++i){cur+=nums[i%n]-nums[(i-ones)%n];best=max(best,cur);}
  return ones-best;
 }
};
